import { Component, OnInit } from '@angular/core';
import { ProductService } from '../../services/product.service';
import { Product, Category } from '../../models/product.model';

@Component({
  selector: 'app-products',
  templateUrl: './products.component.html',
  styleUrls: ['./products.component.css']
})
export class ProductsComponent implements OnInit {
  products: Product[] = [];
  isLoading = false;
  errorMessage = '';
  searchQuery = '';
  selectedCategoryId: number | null = null;
  searchMode: 'category' | 'search' = 'category';

  // Hardcoded sample categories (backend provides category via product, no standalone category endpoint)
  categories: Category[] = [
    { categoryId: 1, categoryName: 'Electronics' },
    { categoryId: 2, categoryName: 'Vehicles' },
    { categoryId: 3, categoryName: 'Real Estate' },
    { categoryId: 4, categoryName: 'Antiques' },
    { categoryId: 5, categoryName: 'Jewellery' },
    { categoryId: 6, categoryName: 'Art' },
    { categoryId: 7, categoryName: 'Fashion' },
    { categoryId: 8, categoryName: 'Other' }
  ];

  constructor(private productService: ProductService) {}

  ngOnInit(): void {
    this.loadByCategory(1);
  }

  loadByCategory(categoryId: number): void {
    this.selectedCategoryId = categoryId;
    this.searchMode = 'category';
    this.isLoading = true;
    this.errorMessage = '';
    this.products = [];

    this.productService.getProductsByCategory(categoryId).subscribe({
      next: (data: Product[]) => {
        this.products = data;
        this.isLoading = false;
      },
      error: (err: { status: number }) => {
        this.isLoading = false;
        this.errorMessage = err.status === 0
          ? 'Cannot connect to server. Please try again later.'
          : 'Failed to load products. Please try again.';
      }
    });
  }

  onSearch(): void {
    const query = this.searchQuery.trim();
    if (!query) return;

    this.searchMode = 'search';
    this.selectedCategoryId = null;
    this.isLoading = true;
    this.errorMessage = '';
    this.products = [];

    this.productService.searchProducts(query).subscribe({
      next: (data: Product[]) => {
        this.products = data;
        this.isLoading = false;
      },
      error: (err: { status: number }) => {
        this.isLoading = false;
        this.errorMessage = err.status === 0
          ? 'Cannot connect to server. Please try again later.'
          : 'Search failed. Please try again.';
      }
    });
  }

  clearSearch(): void {
    this.searchQuery = '';
    this.loadByCategory(1);
  }

  formatCurrency(amount: number): string {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0
    }).format(amount);
  }

  getCategoryName(categoryId: number | null): string {
    if (categoryId === null) return 'All Products';
    const cat = this.categories.find(c => c.categoryId === categoryId);
    return cat ? cat.categoryName : 'Products';
  }

  getStatusClass(status: string): string {
    switch (status) {
      case 'APPROVED': return 'bg-success';
      case 'PENDING': return 'bg-warning text-dark';
      case 'REJECTED': return 'bg-danger';
      default: return 'bg-secondary';
    }
  }
}
<div class="page-wrapper">
  <div class="container-fluid">
    <div class="row g-0">
      <!-- Sidebar: Categories -->
      <div class="col-lg-2 col-md-3 category-sidebar p-3">
        <h6 class="fw-bold text-uppercase text-muted small mb-3">
          <i class="bi bi-tags me-2"></i>Categories
        </h6>
        <div class="d-flex flex-column gap-1">
          <button
            *ngFor="let cat of categories"
            class="btn btn-sm text-start category-btn"
            [ngClass]="selectedCategoryId === cat.categoryId && searchMode === 'category'
              ? 'btn-primary'
              : 'btn-outline-secondary'"
            (click)="loadByCategory(cat.categoryId)">
            {{ cat.categoryName }}
          </button>
        </div>
      </div>

      <!-- Main Content -->
      <div class="col-lg-10 col-md-9 p-4">
        <!-- Search Bar -->
        <div class="card mb-4 shadow-sm">
          <div class="card-body py-3">
            <div class="input-group">
              <span class="input-group-text bg-white border-end-0">
                <i class="bi bi-search text-muted"></i>
              </span>
              <input
                type="text"
                class="form-control border-start-0 ps-0"
                placeholder="Search products by name..."
                [(ngModel)]="searchQuery"
                (keyup.enter)="onSearch()"
              />
              <button class="btn btn-primary" (click)="onSearch()" [disabled]="!searchQuery.trim()">
                Search
              </button>
              <button class="btn btn-outline-secondary" (click)="clearSearch()" *ngIf="searchMode === 'search'">
                <i class="bi bi-x-lg"></i>
              </button>
            </div>
          </div>
        </div>

        <!-- Results Header -->
        <div class="d-flex align-items-center mb-3">
          <h5 class="section-header mb-0 fw-bold">
            <span *ngIf="searchMode === 'category'">
              {{ getCategoryName(selectedCategoryId) }}
            </span>
            <span *ngIf="searchMode === 'search'">
              Search: "{{ searchQuery }}"
            </span>
          </h5>
          <span class="badge bg-primary ms-2" *ngIf="!isLoading">{{ products.length }} products</span>
        </div>

        <!-- Loading -->
        <div class="text-center py-5" *ngIf="isLoading">
          <div class="spinner-border text-primary" role="status"></div>
          <p class="text-muted mt-3">Loading products...</p>
        </div>

        <!-- Error -->
        <div class="alert alert-danger" *ngIf="errorMessage && !isLoading">
          <i class="bi bi-exclamation-triangle me-2"></i>{{ errorMessage }}
        </div>

        <!-- Empty -->
        <div class="text-center py-5" *ngIf="!isLoading && !errorMessage && products.length === 0">
          <i class="bi bi-box-seam display-3 text-muted"></i>
          <p class="text-muted mt-3 fs-5">No products found.</p>
        </div>

        <!-- Product Grid -->
        <div class="row row-cols-1 row-cols-sm-2 row-cols-xl-3 g-4" *ngIf="!isLoading && products.length > 0">
          <div class="col" *ngFor="let product of products">
            <div class="card h-100 product-card">
              <img
                [src]="product.imageUrl || 'assets/no-image.svg'"
                class="card-img-top"
                [alt]="product.productName"
                style="height: 190px; object-fit: cover;"
                (error)="$any($event.target).src = 'assets/no-image.svg'"
              />
              <div class="card-body d-flex flex-column">
                <!-- Status badge -->
                <div class="d-flex justify-content-between align-items-start mb-2">
                  <span class="badge" [ngClass]="getStatusClass(product.verificationStatus)">
                    {{ product.verificationStatus }}
                  </span>
                  <span class="badge bg-light text-dark">{{ product.category.categoryName }}</span>
                </div>

                <h6 class="card-title fw-bold mb-1">{{ product.productName }}</h6>
                <p class="card-text text-muted small flex-grow-1"
                   style="display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;">
                  {{ product.description }}
                </p>

                <div class="mt-2 pt-2 border-top">
                  <div class="d-flex justify-content-between align-items-center">
                    <div>
                      <p class="text-muted small mb-0">Starting Price</p>
                      <p class="fw-bold text-primary mb-0">{{ formatCurrency(product.startingPrice) }}</p>
                    </div>
                    <div class="text-end">
                      <p class="text-muted small mb-0">Seller</p>
                      <p class="fw-semibold small mb-0">{{ product.seller.name }}</p>
                    </div>
                  </div>

                  <!-- Admin Remarks -->
                  <div class="mt-2" *ngIf="product.adminRemarks">
                    <p class="text-muted small mb-0">
                      <i class="bi bi-chat-quote me-1"></i>
                      <em>{{ product.adminRemarks }}</em>
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>
